<?php
require_once __DIR__ . '/ont_seriales_lib.php';
require 'config.php';
require_once 'auditoria.php';
sesionRequerida();

// Asegurar que 'historial' tenga la columna que usa el PDF de remisión
// para relacionar cada registro con su solicitud original.
try {
    $col = $pdo->query("SHOW COLUMNS FROM historial LIKE 'solicitud_id'")->fetch();
    if (!$col) {
        $pdo->exec("ALTER TABLE historial ADD COLUMN solicitud_id VARCHAR(64) DEFAULT NULL");
    } elseif (stripos($col['Type'], 'int') === 0) {
        // Ya existía como INT (versión anterior, incorrecta) — las solicitudes
        // usan IDs de texto tipo "sol_..." que nunca cupieron ahí. Se corrige
        // el tipo de columna para que de aquí en adelante sí se pueda guardar.
        $pdo->exec("ALTER TABLE historial MODIFY solicitud_id VARCHAR(64) DEFAULT NULL");
    }
} catch (\Throwable $e) { error_log('[remision_pdf/columna solicitud_id] '.$e->getMessage()); }

$action = $_GET['action'] ?? '';

if ($action === 'generar') {
    $id   = $_GET['id']   ?? '';
    $tipo = $_GET['tipo'] ?? 'solicitud';

    if (str_starts_with($id, 'pag_')) $tipo = 'pedido_agrupado';
    elseif (str_starts_with($id, 'ped_')) $tipo = 'pedido';
    elseif (str_starts_with($id, 'sol_')) $tipo = 'solicitud';
    elseif ($tipo === 'historial_grupo' || str_contains($id, ',')) $tipo = 'historial_grupo';

    if (!$id) responder(['error' => 'ID requerido'], 400);

    auditar($pdo, 'generar_pdf', 'remisiones', "PDF de remisión generado (tipo: $tipo)", (string)$id);

    // Logo
    $logoB64 = 'data:image/png;base64,';

    // Número de orden
    $stmtOrd = $pdo->prepare("SELECT ultimo FROM orden_consecutivo WHERE tipo = ?");
    $stmtOrd->execute([$tipo === 'gasto' ? 'gasto' : 'solicitud']);
    $ord = $stmtOrd->fetch();
    if (!$ord) {
        $pdo->prepare("INSERT INTO orden_consecutivo (tipo, ultimo) VALUES (?, 1)")->execute([$tipo === 'gasto' ? 'gasto' : 'solicitud']);
        $stmtOrd->execute([$tipo === 'gasto' ? 'gasto' : 'solicitud']);
        $ord = $stmtOrd->fetch();
    }
    $numOrden = 'ORD-' . str_pad($ord['ultimo'], 5, '0', STR_PAD_LEFT);

    // ── INGRESO DE MERCANCÍA (misma estructura visual que la remisión de envío) ──
    if ($tipo === 'ingreso') {
        $h = $pdo->prepare("SELECT * FROM historial WHERE id = ?");
        $h->execute([$id]);
        $reg = $h->fetch();
        if (!$reg) responder(['error' => 'Registro de ingreso no encontrado'], 404);

        $descTxt = $reg['descripcion'] ?? '';
        $proveedor = '—';
        if (preg_match('/Proveedor:\s*([^·]+)/u', $descTxt, $m)) $proveedor = trim($m[1]);
        $nota = '';
        if (preg_match('/·\s*([^·]+?)\s*·\s*Nuevo total/u', ' · '.$descTxt, $m2)) $nota = trim($m2[1]);
        $esRegistro = (bool)preg_match('/^(Registro de|Llegada de|Ingreso ONT)/u', $descTxt);
        if ($esRegistro) {
            // OLT / equipo / carrete / ONT: no hay "Nuevo total"; se muestra el detalle completo
            $nota = $descTxt;
            if (!empty($reg['proveedor'])) $proveedor = trim($reg['proveedor']);
            // Carretes de fibra (también los ya registrados): el proveedor está en el propio carrete
            if (($proveedor === '—' || $proveedor === '') && ($reg['ref'] ?? '') === 'FIBRA' && preg_match('/^Registro de carrete\s+(.+?):/u', $descTxt, $mc)) {
                try {
                    $pc = $pdo->prepare("SELECT proveedor FROM fibra_carretes WHERE codigo = ? ORDER BY id DESC LIMIT 1");
                    $pc->execute([trim($mc[1])]);
                    $pv = trim((string)$pc->fetchColumn());
                    if ($pv !== '') $proveedor = $pv;
                } catch (\Throwable $e) {}
            }
        }
        $destinoIng = htmlspecialchars($reg['destino'] ?: 'Almacén Central');
        $valorUnitario = null; $valorTotal = null; $valorEnvio = null; $valorPorRollo = null; $cantRollos = null;
        if (preg_match('/Valor unitario:\s*\$?([\d.,]+)/u', $descTxt, $mU)) $valorUnitario = trim($mU[1]);
        if (preg_match('/Valor por rollo:\s*\$?([\d.,]+)\s*\((\d+)\s*rollo/u', $descTxt, $mR)) { $valorPorRollo = trim($mR[1]); $cantRollos = trim($mR[2]); }
        if (preg_match('/·\s*Total:\s*\$?([\d.,]+)/u', $descTxt, $mT)) $valorTotal = trim($mT[1]);
        if (preg_match('/Valor de env[ií]o:\s*\$?([\d.,]+)/u', $descTxt, $mE)) $valorEnvio = trim($mE[1]);

        $numOrden = _docNum($pdo, 'ING', 'h' . $id); $color = _docColor('ING');
        $producto = htmlspecialchars($reg['nombre'] ?? '');
        $ref      = htmlspecialchars($reg['ref'] ?? '');
        $unidad   = $reg['unidad_envio'] ?? 'unidad';
        $cantidad = (int)($reg['cantidad'] ?? 0);
        $registradoPor = htmlspecialchars($reg['enviado_por'] ?? '—');
        $fechaGen = date('d/m/Y H:i');
        $fechaIng = $reg['fecha'] ? date('d/m/Y H:i', strtotime($reg['fecha'])) : '—';

        $html = htmlHead("COMPROBANTE DE INGRESO", $numOrden, $color);
        $html .= htmlHeader("COMPROBANTE DE INGRESO", $numOrden, 'INGRESO DE MERCANCÍA', $color, $logoB64);

        $html .= "
        <div class='seccion'>Producto</div>
        <div style='background:#F8FAFC;border:1.5px solid #E2E8F0;border-left:4px solid {$color};border-radius:10px;padding:16px 20px;margin-bottom:18px;'>
          <div style='font-size:11px;font-family:monospace;color:{$color};background:white;padding:2px 8px;border-radius:5px;display:inline-block;border:1px solid #E2E8F0;margin-bottom:6px;'>REF: {$ref}</div>
          <div style='font-size:18px;font-weight:800;color:#0F172A;'>{$producto}</div>
          " . ($proveedor !== '—' ? "<div style='font-size:12px;color:#7C3AED;margin-top:4px;'>🏭 {$proveedor}</div>" : '') . "
          <div style='margin-top:10px;'>
            <div style='font-size:10px;color:#94A3B8;text-transform:uppercase;'>Cantidad ingresada</div>
            <div style='font-size:20px;font-weight:900;color:{$color};'>+{$cantidad}<span style='font-size:13px;font-weight:600;color:#94A3B8;margin-left:4px;'>{$unidad}(s)</span></div>
          </div>
          " . ($valorPorRollo ? "
          <div style='margin-top:12px;display:flex;gap:24px;border-top:1px dashed #E2E8F0;padding-top:10px;'>
            <div><div style='font-size:10px;color:#94A3B8;text-transform:uppercase;'>Valor por rollo</div><div style='font-size:15px;font-weight:800;color:#0F172A;'>\${$valorPorRollo} <span style='font-size:10px;font-weight:600;color:#94A3B8;'>({$cantRollos} rollo(s))</span></div></div>
            <div><div style='font-size:10px;color:#94A3B8;text-transform:uppercase;'>Valor total</div><div style='font-size:15px;font-weight:800;color:{$color};'>\$" . ($valorTotal ?: $valorPorRollo) . "</div></div>
          </div>" : ($valorUnitario ? "
          <div style='margin-top:12px;display:flex;gap:24px;border-top:1px dashed #E2E8F0;padding-top:10px;'>
            <div><div style='font-size:10px;color:#94A3B8;text-transform:uppercase;'>Valor unitario</div><div style='font-size:15px;font-weight:800;color:#0F172A;'>\${$valorUnitario}</div></div>
            <div><div style='font-size:10px;color:#94A3B8;text-transform:uppercase;'>Valor total</div><div style='font-size:15px;font-weight:800;color:{$color};'>\$" . ($valorTotal ?: $valorUnitario) . "</div></div>
          </div>" : '')) . "
          " . ($valorEnvio ? "
          <div style='margin-top:10px;display:flex;gap:24px;" . (($valorUnitario||$valorPorRollo) ? "" : "border-top:1px dashed #E2E8F0;padding-top:10px;") . "'>
            <div><div style='font-size:10px;color:#94A3B8;text-transform:uppercase;'>Valor de envío</div><div style='font-size:15px;font-weight:800;color:#B45309;'>\${$valorEnvio}</div></div>
          </div>" : '') . "
        </div>

        <div class='seccion'>Información del ingreso</div>
        <div class='grid3'>
          <div class='campo'><label>Registrado por</label><span>{$registradoPor}</span></div>
          <div class='campo dest'><label>Destino</label><span>{$destinoIng}</span></div>
          <div class='campo'><label>Fecha de ingreso</label><span>{$fechaIng}</span></div>
        </div>

        " . ($nota ? "<div class='ibox gris'><div class='ibox-titulo'>📝 Nota</div><p>" . htmlspecialchars($nota) . "</p></div>" : '') . "

        <div class='firmas'>
          <div class='firma'>
            <div class='firma-linea'>
              <div class='firma-nombre'>{$registradoPor}</div>
              <div class='firma-cargo'>Registró el ingreso</div>
            </div>
          </div>
          <div class='firma'>
            <div class='firma-linea'>
              <div class='firma-nombre'>_____________________</div>
              <div class='firma-cargo'>Recibió &mdash; {$destinoIng}</div>
            </div>
          </div>
        </div>

        <div class='footer'>
          <span>Integrados S&amp;S &mdash; Sistema de Inventario</span>
          <span>Documento N&deg; {$numOrden} &mdash; Generado el {$fechaGen}</span>
        </div>
        <script>window.onload=function(){window.print();}</script>
        </body></html>";

        header('Content-Type: text/html; charset=utf-8');
        echo $html; exit;
    }

    // ── PEDIDO AGRUPADO ──────────────────────────────────────
    if ($tipo === 'pedido_agrupado') {
        $stmt = $pdo->prepare("SELECT * FROM pedidos_agrupados WHERE id = ?");
        $stmt->execute([$id]);
        $pedido = $stmt->fetch();
        if (!$pedido) responder(['error' => 'Pedido no encontrado'], 404);

        $items = $pdo->prepare("
            SELECT s.*, p.proveedor, p.descripcion as prod_desc, p.metros_por_unidad
            FROM solicitudes s
            LEFT JOIN productos p ON p.ref = s.ref
            WHERE s.pedido_agrupado_id = ?
            ORDER BY s.fecha
        ");
        $items->execute([$id]);
        $itemsData = $items->fetchAll();

        // Buscar datos de seguimiento del pedido agrupado
        $segStmt = $pdo->prepare("SELECT * FROM envios_seguimiento WHERE referencia_id = ? ORDER BY id DESC LIMIT 1");
        $segStmt->execute([$id]);
        $segData = $segStmt->fetch();
        $transportador = $segData ? ($segData['transportador'] ?? '—') : '—';
        $entregadoA    = $segData ? ($segData['entregado_a'] ?? '—') : '—';
        $recibidoPor   = $segData ? ($segData['recibido_por'] ?? '—') : '—';
        $notasDespacho = $segData ? ($segData['notas'] ?? '') : '';
        $fechaEnvio    = ($segData && $segData['fecha_envio'])    ? date('d/m/Y H:i', strtotime($segData['fecha_envio']))    : '—';
        $fechaEntrega  = ($segData && $segData['fecha_entrega'])  ? date('d/m/Y H:i', strtotime($segData['fecha_entrega']))  : '—';
        $fechaRecibido = ($segData && $segData['fecha_recibido']) ? date('d/m/Y H:i', strtotime($segData['fecha_recibido'])) : '—';
        $estadoEnvio   = $segData ? ($segData['estado'] ?? '—') : '—';

        $solicitante = $pedido['solicitado_por'] ?? '';
        $uStmt = $pdo->prepare("SELECT nombre, apellido FROM usuarios WHERE usuario = ?");
        $uStmt->execute([$solicitante]);
        $uData = $uStmt->fetch();
        $nombreSolicitante = trim(($uData['nombre']??'').' '.($uData['apellido']??'')) ?: $solicitante;

        $estadoRaw = $pedido['estado'] ?? 'pendiente';
        $estadoMap = [
            'pendiente'=>'PENDIENTE','en_gestion'=>'EN GESTIÓN',
            'aprobado'=>'APROBADO','parcial'=>'APROBADO PARCIAL',
            'rechazado'=>'RECHAZADO','en_camino'=>'EN CAMINO','recibido'=>'RECIBIDO'
        ];
        $estadoLabel = $estadoMap[$estadoRaw] ?? strtoupper($estadoRaw);
        $colorPrincipal = in_array($estadoRaw,['aprobado','parcial','en_camino','recibido']) ? '#16A871'
            : ($estadoRaw==='rechazado' ? '#B91C1C' : '#BA7517');
        $numOrden = _docNum($pdo, 'SOL', 'pag' . $id); if (!_docEsRojo($colorPrincipal)) $colorPrincipal = _docColor('SOL');

        $fechaSol = $pedido['fecha'] ? date('d/m/Y H:i', strtotime($pedido['fecha'])) : '—';
        $fechaResp = $pedido['fecha_respuesta'] ? date('d/m/Y H:i', strtotime($pedido['fecha_respuesta'])) : '—';
        // Se prioriza quién aprobó DE VERDAD la decisión final (aprobado_por) —
        // "gestionado_por" solo indica quién lo escaló/gestionó en el camino,
        // que puede ser otra persona distinta a quien tomó la decisión final.
        $gestionadoPor = !empty($pedido['aprobado_por']) ? htmlspecialchars($pedido['aprobado_por'])
            : ($pedido['gestionado_por'] ? htmlspecialchars($pedido['gestionado_por']) : 'Administrador');

        // Construir tabla de items
        $tablaItems = '';
        $totalSolicita = 0;
        $totalAprobado = 0;
        foreach ($itemsData as $item) {
            $cantSolRaw   = (float)($item['cantidad'] ?? 0);
            $cantAprobRaw = $item['cantidad_aprobada'] !== null ? (float)$item['cantidad_aprobada'] : $cantSolRaw;
            $totalSolicita += $cantSolRaw;
            $totalAprobado += $cantAprobRaw;
            $estItem = $item['estado'] ?? 'pendiente';
            $estColor = ($estItem==='aprobada') ? '#16A871' : (($estItem==='rechazada') ? '#B91C1C' : '#BA7517');
            $estLabel = ($estItem==='aprobada') ? '✓ Aprobado' : (($estItem==='rechazada') ? '✕ Rechazado' : 'Pendiente');

            // Si el producto viene empacado en rollos iguales (ej: DROP), se
            // entrega el rollo completo — mostrar en rollos, no en metros sueltos
            // (el stock real sigue guardado en metros por dentro).
            $metrosUnidad = !empty($item['metros_por_unidad']) ? (float)$item['metros_por_unidad'] : 0;
            if ($metrosUnidad > 0) {
                $cantSol = fmtCantRollo($cantSolRaw, $metrosUnidad);
                $cantAprob = fmtCantRollo($cantAprobRaw, $metrosUnidad);
            } else {
                $cantSol   = (int)$cantSolRaw;
                $cantAprob = (int)$cantAprobRaw;
            }

            $tablaItems .= "
            <tr>
              <td style='font-family:monospace;font-size:11px;color:#64748B;'>{$item['ref']}</td>
              <td style='font-weight:600;'>" . htmlspecialchars($item['nombre']) . "</td>
              <td style='text-align:center;'>{$cantSol}</td>
              <td style='text-align:center;font-weight:700;color:{$estColor};'>{$cantAprob}</td>
              <td style='text-align:center;'><span style='background:" . ($estItem==='aprobada'?'#EAF3DE':($estItem==='rechazada'?'#FCEBEB':'#FAEEDA')) . ";color:{$estColor};padding:2px 8px;border-radius:5px;font-size:11px;font-weight:700;'>{$estLabel}</span></td>
            </tr>";
        }

        // Seguimiento — buscar el registro con más datos (estado recibido > entregado > en_camino > aprobado)
        $stmtSegPA = $pdo->prepare("
            SELECT * FROM envios_seguimiento 
            WHERE referencia_id = ?
            ORDER BY FIELD(estado,'recibido','entregado','en_camino','aprobado') ASC, id DESC
            LIMIT 1
        ");
        $stmtSegPA->execute([$id]);
        $segPA = $stmtSegPA->fetch() ?: null;

        // Si no encontró, buscar por IDs de solicitudes individuales
        if (!$segPA && !empty($itemsData)) {
            $solIds = array_column($itemsData, 'id');
            $placeholders = implode(',', array_fill(0, count($solIds), '?'));
            $stmtSegPA2 = $pdo->prepare("SELECT * FROM envios_seguimiento WHERE referencia_id IN ($placeholders) ORDER BY FIELD(estado,'recibido','entregado','en_camino','aprobado') ASC, id DESC LIMIT 1");
            $stmtSegPA2->execute($solIds);
            $segPA = $stmtSegPA2->fetch() ?: null;
        }

        // Concatenar notas únicas de todos los items del pedido
        if (!empty($itemsData)) {
            $solIds = array_column($itemsData, 'id');
            $placeholders = implode(',', array_fill(0, count($solIds), '?'));
            $stmtNotas = $pdo->prepare("SELECT DISTINCT notas FROM envios_seguimiento WHERE referencia_id IN ($placeholders) AND notas IS NOT NULL AND notas != ''");
            $stmtNotas->execute($solIds);
            $todasNotas = array_unique(array_column($stmtNotas->fetchAll(), 'notas'));
            if ($segPA && !empty($todasNotas)) {
                $segPA['notas'] = implode("\n", $todasNotas);
            }
        }

        $html = generarHTMLPedidoAgrupado($numOrden, $colorPrincipal, $estadoLabel, $pedido, $nombreSolicitante, $solicitante, $gestionadoPor, $fechaSol, $fechaResp, $tablaItems, $totalSolicita, $totalAprobado, count($itemsData), $logoB64, $segPA);

        header('Content-Type: text/html; charset=utf-8');
        echo $html;
        exit;
    }

    // ── HISTORIAL GRUPO (pedido múltiple desde historial) ──────
    if ($tipo === 'historial_grupo') {
        $ids = array_filter(array_map('intval', explode(',', $id)));
        if (empty($ids)) responder(['error' => 'IDs requeridos'], 400);

        $placeholders = implode(',', array_fill(0, count($ids), '?'));
        $stmt = $pdo->prepare("
            SELECT h.*, u.nombre as nu, u.apellido as au,
                   s.cantidad as cant_solicitada, s.cantidad_aprobada,
                   p.metros_por_unidad
            FROM historial h
            LEFT JOIN usuarios u ON h.enviado_por = u.usuario
            LEFT JOIN solicitudes s ON s.id = h.solicitud_id
            LEFT JOIN productos p ON p.ref = h.ref
            WHERE h.id IN ($placeholders)
            ORDER BY h.fecha ASC
        ");
        $stmt->execute($ids);
        $rows = $stmt->fetchAll();
        if (empty($rows)) responder(['error' => 'Registros no encontrados'], 404);

        $first       = $rows[0];
        $esGastoGrupo = !empty($first['es_gasto']);
        $GLOBALS['_pdfEsDevolucion'] = !$esGastoGrupo && count(array_filter($rows, '_esFilaDevolucionPdf')) === count($rows);

        // ── GASTO MÚLTIPLE: plantilla propia (nada de "solicitado/aprobado/
        //    transportador", que son de un envío, no de un consumo en campo) ──
        if ($esGastoGrupo) {
            $tecnico   = htmlspecialchars($first['enviado_por'] ?? '');
            $stmtU     = $pdo->prepare("SELECT nombre, apellido FROM usuarios WHERE usuario = ?");
            $stmtU->execute([$first['enviado_por']]);
            $uInfo     = $stmtU->fetch();
            $nombreTec = $uInfo ? trim($uInfo['nombre'].' '.$uInfo['apellido']) : $tecnico;
            if (!$nombreTec) $nombreTec = $tecnico;

            $lugar     = htmlspecialchars($first['destino'] ?? '—');
            // Cliente/Proyecto del gasto: todos los registros del lote comparten
            // el mismo, se toma el primero que lo tenga guardado.
            $proyectoG = '';
            foreach ($rows as $rowP) { if (trim($rowP['proyecto_cliente'] ?? '') !== '') { $proyectoG = trim($rowP['proyecto_cliente']); break; } }
            $proyectoG = $proyectoG !== '' ? htmlspecialchars($proyectoG) : '—';
            $fechaGen  = date('d/m/Y H:i');
            $fechaG    = $first['fecha'] ? date('d/m/Y H:i', strtotime($first['fecha'])) : '—';
            $totalCant = array_sum(array_column($rows, 'cantidad'));
            $lat        = $first['gps_lat'] ?? null;
            $lng        = $first['gps_lng'] ?? null;
            $direccionG = ($lat && $lng) ? direccionDesdeCoords($lat, $lng) : '';
            $mapaHtml   = $direccionG
                ? '📍 ' . htmlspecialchars($direccionG)
                : (($lat && $lng)
                    ? "<a href='https://maps.google.com/?q={$lat},{$lng}' target='_blank' style='color:#0369A1;'>📍 Ver ubicación en el mapa ({$lat}, {$lng})</a>"
                    : "<span style='color:#94A3B8;'>Sin ubicación GPS registrada</span>");

            // Observaciones escritas al registrar el gasto (de cualquier producto del lote):
            // "Lugar: X — motivo" (productos normales) o "… · Nota: texto" (ONT / material recogido).
            $obsGasto = [];
            foreach ($rows as $rowO) {
                $dO = (string)($rowO['descripcion'] ?? '');
                if (preg_match('/·\s*Nota:\s*(.+)$/su', $dO, $mO)) $obsGasto[] = trim($mO[1]);
                elseif (preg_match('/^Lugar:[^\n]*?\s—\s(.+)$/su', $dO, $mO)) $obsGasto[] = trim($mO[1]);
            }
            $obsGasto = array_values(array_unique(array_filter($obsGasto)));
            $obsGastoBox = $obsGasto ? "<div class='ibox'><strong>📝 Observaciones:</strong><br>" . nl2br(htmlspecialchars(implode("\n", $obsGasto))) . "</div>" : '';

            $tablaItems = '';
            foreach ($rows as $row) {
                $cant = $row['cantidad'];
                $tablaItems .= "
                <tr>
                  <td style='font-family:monospace;font-size:11px;color:#64748B;'>".htmlspecialchars($row['ref'])."</td>
                  <td style='font-weight:600;'>".htmlspecialchars($row['nombre']).(($sn_ = ontSerialesDeRegistro($pdo, $row)) ? "<div style='font-size:11px;font-weight:600;color:#475569;'>SN: ".htmlspecialchars($sn_)."</div>" : '')."</td>
                  <td style='text-align:center;font-weight:700;color:#92400E;'>{$cant}</td>
                </tr>";
            }

            $numOrden = _docNum($pdo, 'GAS', 'hg' . $id); $color = _docColor('GAS');
            $html  = htmlHead("COMPROBANTE DE GASTO", $numOrden, $color);
            $html .= htmlHeader("COMPROBANTE DE GASTO MÚLTIPLE", $numOrden, "REGISTRADO", $color, $logoB64);
            $html .= "
            <div class='seccion'>Información del gasto</div>
            <div class='grid3'>
              <div class='campo'><label>Registrado por</label><span>{$nombreTec}</span></div>
              <div class='campo'><label>Sede</label><span>{$lugar}</span></div>
              <div class='campo'><label>Fecha</label><span>{$fechaG}</span></div>
              <div class='campo'><label>Total productos</label><span>".count($rows)." tipos</span></div>
              <div class='campo'><label>Total unidades</label><span>{$totalCant}</span></div>
              <div class='campo dest' style='grid-column:1/-1;'><label>Cliente / Proyecto</label><span>🏗️ {$proyectoG}</span></div>
              <div class='campo dest' style='grid-column:1/-1;'><label>Ubicación</label><span>{$mapaHtml}</span></div>
            </div>

            <div class='seccion'>Productos gastados (".count($rows)." productos)</div>
            <table>
              <thead><tr>
                <th style='width:80px;'>Ref.</th>
                <th>Producto</th>
                <th style='width:100px;text-align:center;'>Cantidad</th>
              </tr></thead>
              <tbody>
                {$tablaItems}
                <tr class='total-row'>
                  <td colspan='2' style='text-align:right;'>TOTAL:</td>
                  <td style='text-align:center;color:{$color};font-weight:700;'>{$totalCant}</td>
                </tr>
              </tbody>
            </table>
            {$obsGastoBox}

            <div class='firmas'>
              <div class='firma'><div class='firma-linea'>
                <div class='firma-nombre'>{$nombreTec}</div>
                <div class='firma-cargo'>Registrado por</div>
              </div></div>
            </div>

            <div class='footer'>
              <span>Integrados S&amp;S &mdash; Sistema de Inventario</span>
              <span>Documento N&deg; {$numOrden} &mdash; Generado el {$fechaGen}</span>
            </div>
            <script>window.onload=function(){window.print();}</script>
            </body></html>";

            header('Content-Type: text/html; charset=utf-8');
            echo $html;
            exit;
        }

        // ── ENVÍO/PEDIDO MÚLTIPLE: plantilla original (solicitado/aprobado/
        //    firma de transportador y recibido) ──
        $destino     = htmlspecialchars($first['destino'] ?? '');
        $enviadoPor  = htmlspecialchars($first['enviado_por'] ?? '');
        $fechaGen    = date('d/m/Y H:i');
        $fechaSol    = $first['fecha'] ? date('d/m/Y H:i', strtotime($first['fecha'])) : '—';
        $totalCant   = array_sum(array_column($rows, 'cantidad'));
        $nombreEnv   = trim(($first['nu']??'').' '.($first['au']??'')) ?: $enviadoPor;

        // Buscar info de seguimiento por descripcion (tiene el transportador).
        // La descripción puede traer varios datos juntos separados por "·"
        // (ej: "Recibido en Palermo · Entregado por: palermo · Aprobó: palermo"),
        // así que se extrae solo el pedazo de "Entregado por:" en vez de usar
        // la descripción completa — antes, si no empezaba justo con ese
        // prefijo, se mostraba el texto entero sin recortar.
        $desc0 = $first['descripcion'] ?? '';
        $transportador = '—';
        if (preg_match('/Entregado por:\s*([^·\n]+)/i', $desc0, $mTranspPdf)) {
            $transportador = trim($mTranspPdf[1]);
        } elseif ($desc0 && !preg_match('/Recibido en|Aprob[oó]:/i', $desc0)) {
            // Descripción simple sin el prefijo (formato antiguo) — se usa tal cual.
            $transportador = trim($desc0);
        }

        // Buscar quién solicitó desde envios_seguimiento — "envios_seguimiento"
        // NO tiene columna "solicitud_id" (esa solo existe en "historial"),
        // así que antes esta consulta fallaba siempre (columna inexistente)
        // y nunca encontraba nada; se corrige usando "referencia_id", que es
        // el campo real que enlaza con solicitudes.id.
        $solicitadoPor = '—'; $aprobadoPor = '—'; $notasDespacho = ''; $origenGrupoPdf = '';
        if (!empty($first['solicitud_id'])) {
            $stmtSol = $pdo->prepare("SELECT es.recibido_por, es.notas, es.origen, s.solicitado_por, s.aprobado_por FROM envios_seguimiento es LEFT JOIN solicitudes s ON s.id = es.referencia_id WHERE es.referencia_id = ? AND es.tipo = 'solicitud' LIMIT 1");
            $stmtSol->execute([$first['solicitud_id']]);
            $rowSol = $stmtSol->fetch();
            if ($rowSol) {
                $solicitadoPor = htmlspecialchars($rowSol['solicitado_por'] ?? '—');
                $aprobadoPor   = htmlspecialchars($rowSol['aprobado_por']   ?? '—');
                $notasDespacho = $rowSol['notas'] ?? '';
                $origenGrupoPdf = $rowSol['origen'] ?? '';
            }
        }
        // Sin solicitud detrás (ej: "Asignar Multiple" directo a una persona,
        // o fibra/ONT enviada directo) no hay un id de solicitud que buscar —
        // se busca el envío por los mismos datos del lote (destino + quien
        // envió + los productos del grupo, cerca de la fecha del historial),
        // para poder sacar de sus notas el destinatario puntual
        // ("Recoge en persona" / "Destinatario ONT").
        if (empty($notasDespacho)) {
            try {
                $refsGrupo = array_values(array_unique(array_column($rows, 'ref')));
                $phRefs = implode(',', array_fill(0, count($refsGrupo), '?'));
                $stmtN = $pdo->prepare("
                    SELECT notas, origen FROM envios_seguimiento
                    WHERE destino = ? AND enviado_por = ? AND ref_producto IN ($phRefs)
                      AND notas IS NOT NULL AND notas != ''
                      AND ABS(TIMESTAMPDIFF(MINUTE, COALESCE(fecha_recibido, fecha_entrega, fecha_envio, fecha_aprobado), ?)) <= 30
                ");
                $stmtN->execute([$first['destino'], $first['enviado_por'], ...$refsGrupo, $first['fecha']]);
                $filasNotasPdf = $stmtN->fetchAll();
                $notasArr = array_unique(array_column($filasNotasPdf, 'notas'));
                $notasDespacho = implode("\n", $notasArr);
                if (!$origenGrupoPdf && $filasNotasPdf) $origenGrupoPdf = $filasNotasPdf[0]['origen'] ?? '';
            } catch (\Throwable $e) { error_log('[remision_pdf/historial_grupo notas] ' . $e->getMessage()); }
        }
        // El destinatario puntual de una asignación directa (si lo hay) sale
        // de esas notas — sin esto, "Solicitado por" quedaba en "—" aunque
        // el pedido sí tuviera un destinatario exacto.
        $destinatarioDirectoPdf = '';
        if (preg_match('/Recoge en persona:\s*(.+?)(?:\s+·\s+.*)?$/mu', $notasDespacho, $mDestPdfG)) {
            $destinatarioDirectoPdf = trim($mDestPdfG[1]);
        } elseif (preg_match('/Destinatario ONT:\s*(.+)$/m', $notasDespacho, $mDestPdfG2)) {
            $destinatarioDirectoPdf = trim($mDestPdfG2[1]);
        }
        $labelSolicitadoPorPdf = ($solicitadoPor === '—' && $destinatarioDirectoPdf) ? 'Asignado a' : 'Solicitado por';
        $valorSolicitadoPorPdf = ($solicitadoPor === '—' && $destinatarioDirectoPdf) ? htmlspecialchars($destinatarioDirectoPdf) : $solicitadoPor;
        // Si no hubo solicitud detrás (asignación/envío directo), "Aprobado por"
        // quedaba siempre en "—" aunque la descripción sí traiga quién aprobó
        // (ej: "Aprobó: palermo") — se rescata de ahí como último recurso.
        if ($aprobadoPor === '—' && preg_match('/Aprob[oó]:\s*([^·\n]+)/i', $desc0, $mAprobPdf)) {
            $aprobadoPor = htmlspecialchars(trim($mAprobPdf[1]));
        }

        // Comentario de gestión del pedido agrupado (lo que escribió el admin al
        // aprobar/gestionar) — se busca vía la solicitud vinculada al historial.
        $notaGestion = '';
        $pedidoAgrupadoIdPdf = $first['pedido_agrupado_id'] ?? null;
        if (!empty($first['solicitud_id'])) {
            $stmtPag = $pdo->prepare("SELECT pa.nota, pa.id FROM solicitudes s JOIN pedidos_agrupados pa ON pa.id = s.pedido_agrupado_id WHERE s.id = ? LIMIT 1");
            $stmtPag->execute([$first['solicitud_id']]);
            $rowPag = $stmtPag->fetch();
            if ($rowPag) {
                $notaGestion = $rowPag['nota'] ?: '';
                if (!$pedidoAgrupadoIdPdf) $pedidoAgrupadoIdPdf = $rowPag['id'];
            }
        }
        $notaGestionBox = $notaGestion ? "<div class='ibox gris'><div class='ibox-titulo'>📋 Nota / Gestión del pedido</div><p>" . nl2br(htmlspecialchars($notaGestion)) . "</p></div>" : '';

        // Productos del MISMO pedido múltiple que el admin NO aprobó
        // (rechazados). El historial solo guarda lo que de verdad se
        // entregó, así que estos ítems nunca llegan a $rows — sin esto, el
        // PDF mostraba únicamente lo aprobado, como si el rechazado nunca
        // se hubiera pedido.
        $itemsRechazados = [];
        if ($pedidoAgrupadoIdPdf) {
            $stmtRech = $pdo->prepare("SELECT ref, nombre, cantidad, estado FROM solicitudes WHERE pedido_agrupado_id = ? AND estado = 'rechazada'");
            $stmtRech->execute([$pedidoAgrupadoIdPdf]);
            $itemsRechazados = $stmtRech->fetchAll();
        }

        // Construir tabla de items
        $tablaItems = '';
        foreach ($rows as $row) {
            $cantRaw      = (float)($row['cantidad'] ?? 0);
            $cantSolRaw   = $row['cant_solicitada'] !== null ? (float)$row['cant_solicitada'] : $cantRaw;
            $cantAprobRaw = $row['cantidad_aprobada'] !== null ? (float)$row['cantidad_aprobada'] : $cantRaw;

            // Si el producto viene empacado en rollos iguales (ej: DROP), se
            // entrega el rollo completo — mostrar en rollos, no en metros sueltos.
            $metrosUnidadRow = !empty($row['metros_por_unidad']) ? (float)$row['metros_por_unidad'] : 0;
            if ($metrosUnidadRow > 0) {
                $cantSol = fmtCantRollo($cantSolRaw, $metrosUnidadRow);
                $cantAprob = fmtCantRollo($cantAprobRaw, $metrosUnidadRow);
            } else {
                $cantSol   = (int)$cantSolRaw;
                $cantAprob = (int)$cantAprobRaw;
            }
            $difColor  = $cantAprobRaw < $cantSolRaw ? '#B45309' : '#166534';
            $tablaItems .= "
            <tr>
              <td style='font-family:monospace;font-size:11px;color:#64748B;'>".htmlspecialchars($row['ref'])."</td>
              <td style='font-weight:600;'>".htmlspecialchars($row['nombre']).(($sn_ = ontSerialesDeRegistro($pdo, $row)) ? "<div style='font-size:11px;font-weight:600;color:#475569;'>SN: ".htmlspecialchars($sn_)."</div>" : '').(function() use ($row){ [$tm_, $pv_] = _recogidoInfoDesc($row['descripcion'] ?? ''); return ($pv_ !== '' ? "<div style='font-size:11px;color:#7C3AED;'>🏭 Proveedor: ".htmlspecialchars($pv_)."</div>" : '') . _recogidoPill($tm_); })()."</td>
              <td style='text-align:center;color:#64748B;'>{$cantSol}</td>
              <td style='text-align:center;font-weight:700;color:{$difColor};'>{$cantAprob}</td>
              <td style='text-align:center;'><span style='background:#EAF3DE;color:#166534;padding:2px 8px;border-radius:5px;font-size:11px;font-weight:700;'>✓ Entregado</span></td>
            </tr>";
        }
        $totalSolRechazado = 0;
        foreach ($itemsRechazados as $ir) {
            $cantSolR = (int)($ir['cantidad'] ?? 0);
            $totalSolRechazado += $cantSolR;
            $tablaItems .= "
            <tr>
              <td style='font-family:monospace;font-size:11px;color:#64748B;'>".htmlspecialchars($ir['ref'])."</td>
              <td style='font-weight:600;'>".htmlspecialchars($ir['nombre'])."</td>
              <td style='text-align:center;color:#64748B;'>{$cantSolR}</td>
              <td style='text-align:center;font-weight:700;color:#B91C1C;'>0</td>
              <td style='text-align:center;'><span style='background:#FCEBEB;color:#B91C1C;padding:2px 8px;border-radius:5px;font-size:11px;font-weight:700;'>✕ No aprobado</span></td>
            </tr>";
        }
        $totalProductosPdf = count($rows) + count($itemsRechazados);

        $_pfx = !empty($GLOBALS['_pdfEsDevolucion']) ? 'DEV' : 'ENV';
        $numOrden = _docNum($pdo, $_pfx, 'hg' . $id); $color = _docColor($_pfx);
        $html  = htmlHead("REMISIÓN PEDIDO MÚLTIPLE", $numOrden, $color);
        $html .= htmlHeader("REMISIÓN DE PEDIDO MÚLTIPLE", $numOrden, "ENTREGADO", $color, $logoB64);
        $html .= "
        <div class='seccion'>Información del envío</div>
        <div class='grid3'>
          <div class='campo dest'><label>Destino / Sede</label><span>{$destino}</span></div>
          <div class='campo'><label>{$labelSolicitadoPorPdf}</label><span>{$valorSolicitadoPorPdf}</span></div>
          <div class='campo'><label>Aprobado por</label><span>{$aprobadoPor}</span></div>
          <div class='campo'><label>Enviado por / Transportador</label><span>{$transportador}</span></div>
          <div class='campo'><label>Fecha de envío</label><span>{$fechaSol}</span></div>
          <div class='campo'><label>Total productos</label><span>{$totalProductosPdf} tipos</span></div>
          <div class='campo'><label>Total unidades</label><span>{$totalCant}</span></div>
        </div>

        <div class='seccion'>Productos del pedido ({$totalProductosPdf} productos)</div>
        <table>
          <thead><tr>
            <th style='width:80px;'>Ref.</th>
            <th>Producto</th>
            <th style='width:90px;text-align:center;'>Solicitó</th>
            <th style='width:90px;text-align:center;'>Aprobado</th>
            <th style='width:120px;text-align:center;'>Estado</th>
          </tr></thead>
          <tbody>
            {$tablaItems}
            <tr class='total-row'>
              <td colspan='2' style='text-align:right;'>TOTAL:</td>
              <td style='text-align:center;color:#64748B;font-weight:700;'>".(array_sum(array_map(function($r){
                  return $r['cant_solicitada'] !== null ? (int)$r['cant_solicitada'] : (int)$r['cantidad'];
              }, $rows)) + $totalSolRechazado)."</td>
              <td style='text-align:center;color:{$color};font-weight:700;'>{$totalCant}</td>
              <td></td>
            </tr>
          </tbody>
        </table>
        {$notaGestionBox}
        ".parsearNotas($notasDespacho)."

        <div class='firmas'>
          <div class='firma'><div class='firma-linea'>
            <div class='firma-nombre'>{$nombreEnv}</div>
            <div class='firma-cargo'>Enviado desde " . htmlspecialchars($origenGrupoPdf ?: 'Almacén Central') . "</div>
          </div></div>
          <div class='firma'><div class='firma-linea'>
            <div class='firma-nombre'>{$transportador}</div>
            <div class='firma-cargo'>Transportador</div>
          </div></div>
          <div class='firma'><div class='firma-linea'>
            <div class='firma-nombre'>" . ($destinatarioDirectoPdf ? htmlspecialchars($destinatarioDirectoPdf) : '_____________________') . "</div>
            <div class='firma-cargo'>Recibido por — {$destino}</div>
          </div></div>
        </div>

        <div class='footer'>
          <span>Integrados S&amp;S &mdash; Sistema de Inventario</span>
          <span>Documento N&deg; {$numOrden} &mdash; Generado el {$fechaGen}</span>
        </div>
        <script>window.onload=function(){window.print();}</script>
        </body></html>";

        header('Content-Type: text/html; charset=utf-8');
        echo $html;
        exit;
    }

    // ── SOLICITUD INDIVIDUAL ─────────────────────────────────
    // ── HISTORIAL (cualquier movimiento: fibra, OLT, Mikrotik, etc.) ──
    if ($tipo === 'historial') {
        $idL = preg_replace('/^hist_/', '', $id);
        $stmt = $pdo->prepare("SELECT h.*, p.proveedor, p.descripcion AS prod_desc, p.metros_por_unidad
                               FROM historial h LEFT JOIN productos p ON p.ref = h.ref
                               WHERE h.id = ?");
        $stmt->execute([$idL]);
        $h = $stmt->fetch();
        if (!$h) responder(['error' => "Movimiento {$idL} no encontrado"], 404);
        $GLOBALS['_pdfEsDevolucion'] = _esFilaDevolucionPdf($h);

        // Buscar seguimiento asociado (por ref_producto + destino), si existe
        $seg = null;
        try {
            $stmtSeg = $pdo->prepare("SELECT * FROM envios_seguimiento
                                      WHERE ref_producto = ? AND destino = ?
                                      ORDER BY id DESC LIMIT 1");
            $stmtSeg->execute([$h['ref'], $h['destino']]);
            $seg = $stmtSeg->fetch();
        } catch (\Throwable $e) {}

        // Mapear el registro de historial a la estructura que espera generarHTMLSolicitud
        $doc = [
            'id'                => $h['id'],
            'ref'               => $h['ref'],
            'nombre'            => $h['nombre'],
            'destino'           => $h['destino'],
            'cantidad'          => $h['cantidad'],
            'cantidad_aprobada' => $h['cantidad'],
            'estado'            => 'aprobado',
            'proveedor'         => ($h['proveedor'] ?? '') ?: _recogidoInfoDesc($h['descripcion'] ?? '')[1],
            'tipo_material'     => _recogidoInfoDesc($h['descripcion'] ?? '')[0],
            'prod_desc'         => $h['prod_desc'] ?? '',
            'descripcion'       => $h['descripcion'] ?? '',
            'unidad_envio'      => $h['unidad_envio'] ?? 'unidad',
            'solicitado_por'    => $h['enviado_por'] ?? '',
            'fecha'             => $h['fecha'] ?? null,
            'fecha_respuesta'   => $h['fecha'] ?? null,
            'nu'                => '',
            'au'                => '',
            'solicitud_id'      => $h['solicitud_id'] ?? null,
            'pedido_agrupado_id'=> $h['pedido_agrupado_id'] ?? null,
        ];

        $_pfx = !empty($GLOBALS['_pdfEsDevolucion']) ? 'DEV' : 'ENV';
        $numOrden = _docNum($pdo, $_pfx, 'h' . $id); $colorPrincipal = _docColor($_pfx);
        $estadoLabel       = 'ENTREGADO';
        $nombreSolicitante = $h['enviado_por'] ?? '';
        $fechaSol  = $h['fecha'] ? date('d/m/Y H:i', strtotime($h['fecha'])) : '—';
        $fechaResp = $fechaSol;
        $cantSolRawH = (float)($h['cantidad'] ?? 0);

        // Si el producto viene empacado en rollos iguales (ej: DROP), se
        // entrega el rollo completo — mostrar en rollos, no en metros sueltos.
        $metrosUnidadH = !empty($h['metros_por_unidad']) ? (float)$h['metros_por_unidad'] : 0;
        if ($metrosUnidadH > 0) {
            if (fmod(round($cantSolRawH, 3), $metrosUnidadH) == 0.0) {
                $cantSol = (int)round($cantSolRawH / $metrosUnidadH);
                $doc['unidad_envio'] = 'rollo';
            } else {
                $cantSol = floor($cantSolRawH) == $cantSolRawH ? (int)$cantSolRawH : round($cantSolRawH, 2);
                $doc['unidad_envio'] = 'metro';
            }
        } else {
            $cantSol = (int)$cantSolRawH;
        }
        $cantAprob = $cantSol;

        $html = generarHTMLSolicitud($numOrden, $colorPrincipal, $estadoLabel, $doc, $nombreSolicitante, $fechaSol, $fechaResp, $cantSol, $cantAprob, $seg, $logoB64);
        header('Content-Type: text/html; charset=utf-8');
        echo $html;
        exit;
    }

    if ($tipo === 'solicitud') {
        // Limpiar el ID — puede venir como "sol_123" o solo "123"
        $idL = preg_replace('/^(sol_|pag_|ped_)/', '', $id);

        // Buscar la solicitud directamente
        $stmt = $pdo->prepare("
            SELECT s.*, p.proveedor, p.descripcion as prod_desc, p.metros_por_unidad,
                   u.nombre as nu, u.apellido as au
            FROM solicitudes s
            LEFT JOIN usuarios u ON s.solicitado_por = u.usuario
            LEFT JOIN productos p ON p.ref = s.ref
            WHERE s.id = ?
        ");
        $stmt->execute([$idL]);
        $doc = $stmt->fetch();
        if (!$doc && $idL !== $id) { $stmt->execute([$id]); $doc = $stmt->fetch(); }

        // Si no encuentra directamente, el ID ya ES el solicitud_id — intentar buscar
        // solicitudes cuyo referencia_id coincide en seguimiento
        if (!$doc) {
            // Buscar en envios_seguimiento — referencia_id puede ser el ID de la solicitud
            $stmtSeg = $pdo->prepare("SELECT referencia_id FROM envios_seguimiento WHERE referencia_id = ? AND tipo='solicitud' LIMIT 1");
            $stmtSeg->execute([$idL]);
            $segRow = $stmtSeg->fetch();
            if ($segRow) {
                $stmt->execute([$segRow['referencia_id']]);
                $doc = $stmt->fetch();
            }
        }

        // Si ese número no es una solicitud pero sí un movimiento del historial
        // (asignaciones de ONT/equipos, envíos directos, etc.), se abre como movimiento.
        if (!$doc) {
            $hh = $pdo->prepare("SELECT id FROM historial WHERE id = ?");
            $hh->execute([$idL]);
            if ($hh->fetch()) {
                header('Location: remision_pdf.php?action=generar&tipo=historial&id=hist_' . urlencode($idL));
                exit;
            }
        }

        // FALLBACK FINAL
        if (!$doc) responder(['error' => "Solicitud {$idL} no encontrada. Verifica que la solicitud existe en la BD."], 404);

        // Si la solicitud tiene pedido_agrupado_id → generar PDF del grupo completo
        // (ESTE ES EL CASO PRINCIPAL para pedidos múltiples)
        if (!$doc) {
            // El id puede ser el solicitud_id del historial (referencia_id del seguimiento)
            // Buscar la solicitud por referencia_id en envios_seguimiento
            $stmtSeg0 = $pdo->prepare("SELECT referencia_id, tipo FROM envios_seguimiento WHERE id = ? OR referencia_id = ? LIMIT 1");
            $stmtSeg0->execute([$idL, $idL]);
            $seg0 = $stmtSeg0->fetch();
            if ($seg0 && $seg0['tipo'] === 'solicitud') {
                $stmt->execute([$seg0['referencia_id']]);
                $doc = $stmt->fetch();
            }
            // Si aun no encuentra, buscar pedido_agrupado que tenga solicitudes con ese referencia_id
            if (!$doc) {
                $stmtPagId = $pdo->prepare("SELECT pedido_agrupado_id FROM solicitudes WHERE id = ? AND pedido_agrupado_id IS NOT NULL LIMIT 1");
                $stmtPagId->execute([$idL]);
                $pagRow = $stmtPagId->fetch();
                if (!$pagRow) {
                    // Buscar en historial por solicitud_id
                    $stmtH = $pdo->prepare("SELECT solicitud_id FROM historial WHERE id = ? OR solicitud_id = ? LIMIT 1");
                    $stmtH->execute([$idL, $idL]);
                    $hRow = $stmtH->fetch();
                    if ($hRow && $hRow['solicitud_id']) {
                        $stmtPagId->execute([$hRow['solicitud_id']]);
                        $pagRow = $stmtPagId->fetch();
                        if (!$pagRow) {
                            // El solicitud_id del historial ES el id de la solicitud
                            $stmt->execute([$hRow['solicitud_id']]);
                            $doc = $stmt->fetch();
                        }
                    }
                }
                if (!$doc && $pagRow && !empty($pagRow['pedido_agrupado_id'])) {
                    // Generar PDF del grupo — simular $doc con pedido_agrupado_id
                    $doc = ['pedido_agrupado_id' => $pagRow['pedido_agrupado_id']];
                }
            }
        }

        // Si la solicitud tiene pedido_agrupado_id, generar PDF del grupo completo
        if ($doc && !empty($doc['pedido_agrupado_id'])) {
            // Redirigir internamente a pedido_agrupado
            $tipo = 'pedido_agrupado';
            $id   = $doc['pedido_agrupado_id'];
            // Re-ejecutar como pedido_agrupado
            $stmtPag = $pdo->prepare("SELECT * FROM pedidos_agrupados WHERE id = ?");
            $stmtPag->execute([$id]);
            $pedido = $stmtPag->fetch();
            if ($pedido) {
                $items = $pdo->prepare("SELECT s.*, p.proveedor, p.descripcion as prod_desc, p.metros_por_unidad FROM solicitudes s LEFT JOIN productos p ON p.ref = s.ref WHERE s.pedido_agrupado_id = ? ORDER BY s.fecha");
                $items->execute([$id]);
                $itemsData = $items->fetchAll();
                $segStmt = $pdo->prepare("SELECT * FROM envios_seguimiento WHERE referencia_id = ? ORDER BY id DESC LIMIT 1");
                $segStmt->execute([$id]);
                $segPA = $segStmt->fetch() ?: null;
                if (!$segPA && !empty($itemsData)) {
                    $solIds = array_column($itemsData, 'id');
                    $ph = implode(',', array_fill(0, count($solIds), '?'));
                    $s2 = $pdo->prepare("SELECT * FROM envios_seguimiento WHERE referencia_id IN ($ph) ORDER BY FIELD(estado,'recibido','entregado','en_camino','aprobado') ASC, id DESC LIMIT 1");
                    $s2->execute($solIds);
                    $segPA = $s2->fetch() ?: null;
                }
                $solicitante = $pedido['solicitado_por'] ?? '';
                $uStmt = $pdo->prepare("SELECT nombre, apellido FROM usuarios WHERE usuario = ?");
                $uStmt->execute([$solicitante]);
                $uData = $uStmt->fetch();
                $nombreSolicitante = trim(($uData['nombre']??'').' '.($uData['apellido']??'')) ?: $solicitante;
                $tablaItems = ''; $totalSol = 0; $totalAprob = 0;
                foreach ($itemsData as $item) {
                    $cantSolRaw = (float)($item['cantidad']??0);
                    $cantAprobRaw = $item['cantidad_aprobada'] !== null ? (float)$item['cantidad_aprobada'] : $cantSolRaw;
                    $totalSol += $cantSolRaw; $totalAprob += $cantAprobRaw;
                    $estItem = $item['estado']??'pendiente';
                    $estColor = $estItem==='aprobada'?'#16A871':($estItem==='rechazada'?'#B91C1C':'#BA7517');
                    $estLabel = $estItem==='aprobada'?'✓ Aprobado':($estItem==='rechazada'?'✕ Rechazado':'Pendiente');
                    // Si el producto viene empacado en rollos iguales (ej: DROP), se
                    // entrega el rollo completo — mostrar en rollos, no en metros sueltos.
                    $metrosUnidad = !empty($item['metros_por_unidad']) ? (float)$item['metros_por_unidad'] : 0;
                    if ($metrosUnidad > 0) {
                        $cantSol = fmtCantRollo($cantSolRaw, $metrosUnidad);
                $cantAprob = fmtCantRollo($cantAprobRaw, $metrosUnidad);
                    } else {
                        $cantSol = (int)$cantSolRaw;
                        $cantAprob = (int)$cantAprobRaw;
                    }
                    $tablaItems .= "<tr><td style='font-family:monospace;font-size:11px;color:#64748B;'>{$item['ref']}</td><td style='font-weight:600;'>".htmlspecialchars($item['nombre'])."</td><td style='text-align:center;'>{$cantSol}</td><td style='text-align:center;font-weight:700;color:{$estColor};'>{$cantAprob}</td><td style='text-align:center;'><span style='background:".($estItem==='aprobada'?'#EAF3DE':($estItem==='rechazada'?'#FCEBEB':'#FAEEDA')).";color:{$estColor};padding:2px 8px;border-radius:5px;font-size:11px;font-weight:700;'>{$estLabel}</span></td></tr>";
                }
                $estadoRaw = $pedido['estado']??'pendiente';
                $estadoMap = ['pendiente'=>'PENDIENTE','en_gestion'=>'EN GESTIÓN','aprobado'=>'APROBADO','parcial'=>'APROBADO PARCIAL','rechazado'=>'RECHAZADO','en_camino'=>'EN CAMINO','recibido'=>'RECIBIDO'];
                $estadoLabel = $estadoMap[$estadoRaw] ?? strtoupper($estadoRaw);
                $colorPrincipal = in_array($estadoRaw,['aprobado','parcial','en_camino','recibido'])?'#16A871':($estadoRaw==='rechazado'?'#B91C1C':'#BA7517');
                $numOrden = _docNum($pdo, 'SOL', 'pag' . $id); if (!_docEsRojo($colorPrincipal)) $colorPrincipal = _docColor('SOL');
                $fechaSol = $pedido['fecha'] ? date('d/m/Y H:i', strtotime($pedido['fecha'])) : '—';
                $fechaResp = $pedido['fecha_respuesta'] ? date('d/m/Y H:i', strtotime($pedido['fecha_respuesta'])) : '—';
                $gestionadoPor = !empty($pedido['aprobado_por']) ? $pedido['aprobado_por']
                    : ($pedido['gestionado_por'] ?? 'Administrador');
                $html = generarHTMLPedidoAgrupado($numOrden, $colorPrincipal, $estadoLabel, $pedido, $nombreSolicitante, $solicitante, $gestionadoPor, $fechaSol, $fechaResp, $tablaItems, $totalSol, $totalAprob, count($itemsData), $logoB64, $segPA);
                header('Content-Type: text/html; charset=utf-8');
                echo $html; exit;
            }
        }

        // Buscar en seguimiento para info de despacho
        $seg = null;
        if ($doc) {
            $stmtSeg = $pdo->prepare("SELECT * FROM envios_seguimiento WHERE referencia_id = ? OR referencia_id = ? ORDER BY fecha_envio DESC, id DESC LIMIT 1");
            $stmtSeg->execute([$idL, $id]);
            $seg = $stmtSeg->fetch();
            // Si no encontró, buscar por pedido_agrupado_id del doc
            if (!$seg && !empty($doc['pedido_agrupado_id'])) {
                $stmtSeg2 = $pdo->prepare("SELECT * FROM envios_seguimiento WHERE referencia_id = ? ORDER BY id DESC LIMIT 1");
                $stmtSeg2->execute([$doc['pedido_agrupado_id']]);
