        if (!$doc) responder(['error' => 'Solicitud no encontrada'], 404);

        $estadoRaw   = $doc['estado'] ?? 'pendiente';
        $colorPrincipal = in_array($estadoRaw,['aprobada','aprobado']) ? '#16A871'
            : (in_array($estadoRaw,['rechazada','rechazado']) ? '#B91C1C' : '#BA7517');
        $numOrden = _docNum($pdo, 'SOL', 'sol' . $id); if (!_docEsRojo($colorPrincipal)) $colorPrincipal = _docColor('SOL');
        $estadoLabel = match($estadoRaw) {
            'aprobada','aprobado' => 'APROBADO',
            'rechazada','rechazado' => 'RECHAZADO',
            'pendiente' => 'PENDIENTE',
            'en_gestion' => 'EN GESTIÓN',
