        $nombreSolicitante = trim(($doc['nu']??'').' '.($doc['au']??'')) ?: ($doc['solicitado_por']??'');
        $fechaSol  = $doc['fecha'] ? date('d/m/Y H:i', strtotime($doc['fecha'])) : '—';
        $fechaResp = $doc['fecha_respuesta'] ? date('d/m/Y H:i', strtotime($doc['fecha_respuesta'])) : '—';
        $cantSolRaw   = (float)($doc['cantidad'] ?? 0);
        $cantAprobRaw = $doc['cantidad_aprobada'] !== null ? (float)$doc['cantidad_aprobada'] : $cantSolRaw;

        // Si el producto viene empacado en rollos iguales (ej: DROP), se
        // entrega el rollo completo — mostrar en rollos, no en metros sueltos.
        $metrosUnidadSol = !empty($doc['metros_por_unidad']) ? (float)$doc['metros_por_unidad'] : 0;
        if ($metrosUnidadSol > 0) {
            $enteroS = fmod(round($cantSolRaw, 3), $metrosUnidadSol) == 0.0;
            $enteroA = fmod(round($cantAprobRaw, 3), $metrosUnidadSol) == 0.0;
            if ($enteroS && $enteroA) {
                $cantSol   = (int)round($cantSolRaw / $metrosUnidadSol);
                $cantAprob = (int)round($cantAprobRaw / $metrosUnidadSol);
                $doc['unidad_envio'] = 'rollo';
            } else {
                $cantSol   = floor($cantSolRaw) == $cantSolRaw ? (int)$cantSolRaw : round($cantSolRaw, 2);
                $cantAprob = floor($cantAprobRaw) == $cantAprobRaw ? (int)$cantAprobRaw : round($cantAprobRaw, 2);
                $doc['unidad_envio'] = 'metro';
            }
        } else {
            $cantSol   = (int)$cantSolRaw;
            $cantAprob = (int)$cantAprobRaw;
        }

        $html = generarHTMLSolicitud($numOrden, $colorPrincipal, $estadoLabel, $doc, $nombreSolicitante, $fechaSol, $fechaResp, $cantSol, $cantAprob, $seg, $logoB64);

        header('Content-Type: text/html; charset=utf-8');
        echo $html;
        exit;
    }

    // ── GASTO ────────────────────────────────────────────────
    if ($tipo === 'gasto') {
        $stmt = $pdo->prepare("
            SELECT h.*, u.nombre as nu, u.apellido as au
            FROM historial h
