        ");
        $stmt->execute([$id]);
        $doc = $stmt->fetch();
        if (!$doc) responder(['error' => 'Gasto no encontrado'], 404);

        $esVenta    = !empty($doc['es_venta']);
        $destino    = htmlspecialchars($doc['destino'] ?? '');
        $enviado    = htmlspecialchars($doc['enviado_por'] ?? '');
        $nombre     = trim(($doc['nu']??'').' '.($doc['au']??'')) ?: $enviado;
        $fecha      = $doc['fecha'] ? date('d/m/Y H:i', strtotime($doc['fecha'])) : '—';
        $fechaGen   = date('d/m/Y H:i');
        $cantidad   = (int)($doc['cantidad'] ?? 0);
        $ref        = htmlspecialchars($doc['ref'] ?? '—');
        $nomProd    = htmlspecialchars($doc['nombre'] ?? '—');
        // La descripción a veces trae texto técnico embebido ("Stock: ♻️
        // Recuperado", "Prestado por X, usado por Y") — eso ya se muestra
        // aparte como etiqueta, así que no hace falta repetirlo dentro del
        // cuadro de motivo/descripción.
        $descRaw    = $doc['descripcion'] ?? '';
        $desc       = htmlspecialchars(trim(preg_replace('/Stock:\s*♻️\s*Recuperado|Prestado por [^,]+, usado por .+$/i', '', $descRaw)));
        $esRecuperado = stripos($descRaw, 'Stock: ♻️ Recuperado') !== false || stripos($descRaw, '[STOCK:recuperado]') !== false;
        $proyecto   = htmlspecialchars($doc['proyecto_cliente'] ?? '');
        $lat        = $doc['gps_lat'] ?? null;
        $lng        = $doc['gps_lng'] ?? null;

        $_pfx = $esVenta ? 'VEN' : 'GAS';
        $numOrden = _docNum($pdo, $_pfx, 'h' . $id); $color = _docColor($_pfx);
        $tituloDoc  = $esVenta ? 'COMPROBANTE DE VENTA' : 'COMPROBANTE DE GASTO';
        $tituloSub  = $esVenta ? 'VENTA' : 'GASTO';

        $html = htmlHeader($tituloDoc, $numOrden, $tituloSub, $color, $logoB64);
        $html .= "<style>
            body{font-family:Arial,sans-serif;font-size:11px;color:#1E293B;background:#fff;padding:18px;}
            .header{display:flex;justify-content:space-between;align-items:flex-start;padding-bottom:10px;border-bottom:4px solid {$color};margin-bottom:14px;}
            .seccion{font-size:10px;font-weight:700;color:#94A3B8;text-transform:uppercase;letter-spacing:1px;margin:10px 0 6px;}
            .grid3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:8px;}
            .campo{background:#F8FAFC;border:1px solid #E2E8F0;border-radius:6px;padding:5px 10px;}
            .campo label{font-size:9px;color:#94A3B8;text-transform:uppercase;display:block;margin-bottom:3px;}
            .campo span{font-size:12px;font-weight:600;color:#0F172A;}
            .ibox{background:#FFFBEB;border-left:4px solid #FCD34D;border-radius:6px;padding:8px 12px;margin:10px 0;font-size:11px;}
            .firmas{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px;}
            .firma-box{border-top:1.5px solid #CBD5E1;padding-top:8px;text-align:center;font-size:11px;color:#475569;}
        </style>";

        $etiquetas = '';
        if ($esRecuperado) $etiquetas .= "<span style='display:inline-block;background:#EAF3DE;color:#166534;font-size:10px;font-weight:700;padding:2px 8px;border-radius:5px;margin-right:6px;'>♻️ Stock recuperado</span>";
        if ($proyecto && $esVenta) $etiquetas .= "<span style='display:inline-block;background:#FFFBEB;color:#B45309;font-size:10px;font-weight:700;padding:2px 8px;border-radius:5px;margin-right:6px;'>🏗️ {$proyecto}</span>";
        if ($etiquetas) $html .= "<div style='margin-bottom:10px;'>{$etiquetas}</div>";

        $html .= "<div class='seccion'>Información del " . ($esVenta ? 'venta' : 'gasto') . "</div>
        <div class='grid3'>
          <div class='campo'><label>Sede / Destino</label><span>{$destino}</span></div>
          <div class='campo'><label>Registrado por</label><span>{$nombre}</span></div>
          <div class='campo'><label>Fecha</label><span>{$fecha}</span></div>
          " . (!$esVenta ? "<div class='campo' style='grid-column:1/-1;'><label>Cliente / Proyecto</label><span>🏗️ " . ($proyecto !== '' ? $proyecto : '—') . "</span></div>" : '') . "
        </div>";

        if ($esVenta) {
