            $formaPago   = htmlspecialchars($doc['forma_pago'] ?? '—');
            $precioUnit  = $doc['precio_unitario'] !== null ? number_format((float)$doc['precio_unitario'], 0, ',', '.') : null;
            $precioTotal = $doc['precio_total'] !== null ? number_format((float)$doc['precio_total'], 0, ',', '.') : null;
            $html .= "<div class='grid3' style='margin-top:8px;'>
              <div class='campo'><label>Cliente</label><span>{$cliente}</span></div>
              <div class='campo'><label>Forma de pago</label><span>{$formaPago}</span></div>
              <div class='campo'><label>Precio unitario</label><span>" . ($precioUnit !== null ? "\${$precioUnit}" : '—') . "</span></div>
            </div>";
        }

        if ($lat && $lng) {
            $direccionS = direccionDesdeCoords($lat, $lng);
            $html .= $direccionS
                ? "<div style='margin-bottom:10px;font-size:11px;color:#1E293B;'>📍 " . htmlspecialchars($direccionS) . "</div>"
                : "<div style='margin-bottom:10px;'><a href='https://maps.google.com/?q={$lat},{$lng}' style='font-size:11px;color:#0369A1;'>📍 Ver ubicación en el mapa ({$lat}, {$lng})</a></div>";
