            <th style='padding:6px 8px;text-align:center;border-bottom:1px solid #E2E8F0;'>Cantidad</th>
            " . ($esVenta ? "<th style='padding:6px 8px;text-align:right;border-bottom:1px solid #E2E8F0;'>Total</th>" : "") . "
