        ".($desc ? "<div class='ibox'><strong>📝 Motivo / Descripción:</strong><br>{$desc}</div>" : "")."
        <div class='firmas'>
          <div class='firma-box'>{$nombre}<br><span style='font-size:10px;color:#94A3B8;'>Registrado por &mdash; {$destino}</span></div>
          <div class='firma-box'>___________________<br><span style='font-size:10px;color:#94A3B8;'>Recibido por &mdash; {$destino}</span></div>
