        $stmt->execute([$id]);
        $doc = $stmt->fetch();
        if (!$doc) { $stmt->execute([preg_replace('/^ped_/','',$id)]); $doc = $stmt->fetch(); }
        if (!$doc) responder(['error' => 'Pedido no encontrado'], 404);

        $estadoRaw = $doc['estado'] ?? 'pendiente';
        $colorPrincipal = in_array($estadoRaw,['atendido','aprobado']) ? '#16A871' : ($estadoRaw==='rechazado' ? '#B91C1C' : '#BA7517');
        $numOrden = _docNum($pdo, 'SOL', 'ped' . $id); if (!_docEsRojo($colorPrincipal)) $colorPrincipal = _docColor('SOL');
        $estadoLabel = match($estadoRaw) {
            'atendido','aprobado'=>'ATENDIDO','rechazado'=>'RECHAZADO',
            'en_gestion'=>'EN GESTIÓN','pendiente'=>'PENDIENTE',default=>strtoupper($estadoRaw)
        };
        $nombreSolicitante = trim(($doc['nu']??'').' '.($doc['au']??'')) ?: ($doc['solicitado_por']??'');
        $fechaSol  = $doc['fecha'] ? date('d/m/Y H:i', strtotime($doc['fecha'])) : '—';
        $fechaResp = $doc['fecha_respuesta'] ? date('d/m/Y H:i', strtotime($doc['fecha_respuesta'])) : '—';

        $html = generarHTMLPedidoMunicipio($numOrden, $colorPrincipal, $estadoLabel, $doc, $nombreSolicitante, $fechaSol, $fechaResp, $logoB64);
        header('Content-Type: text/html; charset=utf-8');
        echo $html;
        exit;
    }

    responder(['error' => 'Tipo no reconocido'], 400);
}

// ════════════════════════════════════════════════════════════
// FUNCIONES GENERADORAS DE HTML
// ════════════════════════════════════════════════════════════

// Convierte coordenadas GPS en una dirección legible (ej: "Cra 5 #10-20,
// Palermo, Huila"), para que el PDF muestre la dirección en texto en vez de
// un link o un mapa — usa el servicio gratuito de Nominatim (OpenStreetMap).
// Si no hay internet o el servicio no responde, devuelve cadena vacía y el
// PDF simplemente no muestra el campo de dirección (no falla).
function direccionDesdeCoords($lat, $lng): string {
    if (!$lat || !$lng) return '';
    try {
        $url = "https://nominatim.openstreetmap.org/reverse?format=json&lat=" . urlencode($lat) . "&lon=" . urlencode($lng) . "&zoom=18&addressdetails=0&accept-language=es";
        $ctx = stream_context_create(['http' => [
            'header'  => "User-Agent: IntegradosSyS-Inventario/1.0\r\n",
            'timeout' => 2,
        ]]);
        $resp = @file_get_contents($url, false, $ctx);
        if (!$resp) return '';
        $data = json_decode($resp, true);
        return trim($data['display_name'] ?? '');
    } catch (\Throwable $e) { return ''; }
}

/* Cantidad de un producto "por rollo": rollos enteros -> "2 rollos"; si hay una parte de rollo
   (ej. 800 m de un rollo de 1000) se muestra en METROS, nunca como 0.8 rollo. */
function fmtCantRollo(float $raw, float $mpu): string {
    $esEntero = fmod(round($raw, 3), $mpu) == 0.0;
    if ($esEntero) { $r = (int)round($raw / $mpu); return $r . ' rollo' . ($r != 1 ? 's' : ''); }
    $m = floor($raw) == $raw ? (int)$raw : round($raw, 2);
    return $m . ' m';
}

/* Quita las líneas internas del sistema (lote, quién recoge, rollos elegidos…) y las
   repetidas: no son notas de personas y no deben salir en el PDF. */
function limpiarNotasPdf(string $notas): string {
    $notas = str_replace('\\n', "\n", $notas);
    $internas = '/^\s*(Lote:|Recoge en persona:|Destinatario ONT:|Rollos? elegidos?:|Devoluci[oó]n:\s*s[ií]|\[STOCK:)/iu';
    $lineas = [];
    foreach (preg_split('/\R/u', $notas) as $l) {
        $l = trim($l);
        if ($l === '' || preg_match($internas, $l)) continue;
        if (!in_array($l, $lineas, true)) $lineas[] = $l;
    }
    // Si una línea es solo el comienzo de otra más completa, se queda la completa
    $res = [];
    foreach ($lineas as $i => $l) {
        $repetida = false;
        foreach ($lineas as $j => $o) {
            if ($i !== $j && mb_strlen($o) > mb_strlen($l) && mb_strpos($o, $l) === 0) { $repetida = true; break; }
        }
        if (!$repetida) $res[] = $l;
    }
    return implode("\n", $res);
}

function _filaInfoPdf(string $etq, string $valor): string {
    return "<div style='padding:8px 0;border-bottom:1px solid #F1F5F9;'>"
         . "<div style='font-size:9px;color:#94A3B8;text-transform:uppercase;letter-spacing:.6px;'>{$etq}</div>"
         . "<div style='font-size:13px;font-weight:700;color:#0F172A;margin-top:2px;'>{$valor}</div></div>";
}
function _badgeEstadoPdf(string $estado, string $color): string {
    $m = ['pendiente'=>'Pendiente','en_camino'=>'En camino','entregado'=>'Entregado','recibido'=>'Recibido','rechazado'=>'Rechazado','cancelado'=>'Cancelado'];
    $t = $m[$estado] ?? ($estado !== '' ? ucfirst(str_replace('_',' ',$estado)) : '—');
    return "<span style='display:inline-block;padding:2px 10px;border-radius:99px;background:{$color};color:white;font-size:10px;font-weight:700;text-transform:none;letter-spacing:0;'>" . htmlspecialchars($t) . "</span>";
}
/* Línea de tiempo horizontal: cada paso = [título, fecha, responsable]. Pasos sin fecha ('—') salen en gris. */
function _lineaTiempoPdf(array $pasos, string $color): string {
    $n = count($pasos);
    $h = "<div style='display:flex;margin-bottom:16px;border:1.5px solid #E2E8F0;border-radius:10px;padding:14px 8px 12px;'>";
    foreach ($pasos as $i => [$tit, $fecha, $quien]) {
        $f = trim(strip_tags((string)$fecha));
        $hecho = $f !== '' && $f !== '—';
        $c = $hecho ? $color : '#CBD5E1';
        $izq = $i > 0 ? "<div style='flex:1;height:3px;background:" . ($hecho ? $color : '#E2E8F0') . ";'></div>" : "<div style='flex:1;'></div>";
        $der = $i < $n - 1 ? "<div style='flex:1;height:3px;background:#E2E8F0;'></div>" : "<div style='flex:1;'></div>";
        $h .= "<div style='flex:1;text-align:center;min-width:0;'>"
            . "<div style='display:flex;align-items:center;margin-bottom:8px;'>{$izq}<div style='width:20px;height:20px;border-radius:50%;background:{$c};color:white;font-size:12px;line-height:20px;font-weight:700;'>" . ($hecho ? '✓' : '') . "</div>{$der}</div>"
            . "<div style='font-size:11px;font-weight:800;color:" . ($hecho ? '#0F172A' : '#94A3B8') . ";'>{$tit}</div>"
            . "<div style='font-size:10px;color:#475569;margin-top:2px;'>{$fecha}</div>"
            . "<div style='font-size:10px;color:#94A3B8;margin-top:1px;padding:0 4px;word-break:break-word;'>{$quien}</div>"
            . "</div>";
    }
    return $h . "</div>";
}

function parsearNotas(string $notas): string {
    $notas = limpiarNotasPdf($notas);
    if (empty(trim($notas))) return '';
    // Separar por etiquetas [Entrega] y [Recibido]
    $partes = preg_split('/\[(Despacho|Entrega|Recibido)\]/', $notas, -1, PREG_SPLIT_DELIM_CAPTURE);
    $html = "<div class='ibox gris' style='margin-bottom:12px;'><div class='ibox-titulo'>📝 Notas y observaciones</div>";
    $etiqueta = '';
    foreach ($partes as $i => $parte) {
        $parte = trim($parte);
        if (empty($parte)) continue;
        if (in_array($parte, ['Despacho', 'Entrega', 'Recibido'])) {
            $etiqueta = $parte;
        } else {
            $iconos = ['Despacho'=>'🚚','Entrega'=>'📦','Recibido'=>'✅'];
            $colores = ['Despacho'=>'#1E40AF','Entrega'=>'#7C3AED','Recibido'=>'#166534'];
            $icon  = $iconos[$etiqueta]  ?? '📝';
            $color = $colores[$etiqueta] ?? '#475569';
            $label = $etiqueta ?: 'General';
            $html .= "<div style='margin-top:8px;padding:8px 12px;background:white;border-radius:6px;border-left:3px solid {$color};'>
                <div style='font-size:10px;font-weight:700;color:{$color};text-transform:uppercase;margin-bottom:3px;'>{$icon} {$label}</div>
                <p style='font-size:12px;color:#0F172A;line-height:1.5;'>" . htmlspecialchars($parte) . "</p>
            </div>";
            $etiqueta = '';
        }
    }
    // Si solo hay una parte Y ya se mostró en el foreach, no duplicar
    // (el foreach ya lo mostró como 'General')
    $html .= "</div>";
    return $html;
}

