/* Número y color por TIPO de documento. Cada documento conserva su número (no cambia
   al volver a generar el PDF) y cada tipo tiene su propio consecutivo y color. */
function _docColor(string $pref): string {
    return ['VEN'=>'#166534','GAS'=>'#BA7517','DEV'=>'#7C3AED','ING'=>'#0F766E','ENV'=>'#0C6EDE','SOL'=>'#4F46E5'][$pref] ?? '#0C6EDE';
}
function _docNum($pdo, string $pref, string $clave): string {
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS doc_numeros (clave VARCHAR(190) NOT NULL PRIMARY KEY, prefijo VARCHAR(10) NOT NULL, numero INT NOT NULL, creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $clave = substr($pref . ':' . $clave, 0, 190);
        $q = $pdo->prepare("SELECT prefijo, numero FROM doc_numeros WHERE clave = ?");
        $q->execute([$clave]);
        if ($r = $q->fetch()) return $r['prefijo'] . '-' . str_pad($r['numero'], 5, '0', STR_PAD_LEFT);
        $pdo->prepare("INSERT IGNORE INTO orden_consecutivo (tipo, ultimo) VALUES (?, 0)")->execute(['doc_' . $pref]);
        $pdo->prepare("UPDATE orden_consecutivo SET ultimo = LAST_INSERT_ID(ultimo + 1) WHERE tipo = ?")->execute(['doc_' . $pref]);
        $n = (int)$pdo->query("SELECT LAST_INSERT_ID()")->fetchColumn();
        $pdo->prepare("INSERT IGNORE INTO doc_numeros (clave, prefijo, numero) VALUES (?, ?, ?)")->execute([$clave, $pref, $n]);
        $q->execute([$clave]);
        if ($r = $q->fetch()) return $r['prefijo'] . '-' . str_pad($r['numero'], 5, '0', STR_PAD_LEFT);
    } catch (\Throwable $e) { error_log('[remision_pdf/_docNum] ' . $e->getMessage()); }
    return $pref . '-00000';
}
function _docEsRojo($c): bool { return $c === '#B91C1C'; }

/* Material recogido: saca "Recogido reutilizable/dañado" y el proveedor de la descripción del historial. */
function _recogidoInfoDesc(string $d): array {
    $tipo = ''; $prov = '';
    if (preg_match('/(Recogido (?:reutilizable|dañado)(?: \(\d+\) \+ dañado \(\d+\))?)/u', $d, $m)) $tipo = $m[1];
    if (preg_match('/Proveedor:\s*([^·]+)/u', $d, $m2)) $prov = trim($m2[1]);
    return [$tipo, $prov];
}
function _recogidoPill(string $tipo): string {
    if ($tipo === '') return '';
    $dan = (strpos($tipo, 'dañado') !== false && strpos($tipo, 'reutilizable') === false);
    $mix = (strpos($tipo, '+') !== false);
    $bg = $dan ? '#FCEBEB' : ($mix ? '#FEF3C7' : '#EAF3DE'); $fg = $dan ? '#B91C1C' : ($mix ? '#92400E' : '#166534');
    $ico = $dan ? '🛠' : '♻️';
    return "<span style='display:inline-block;background:{$bg};color:{$fg};padding:2px 9px;border-radius:99px;font-size:11px;font-weight:700;margin-top:5px;'>{$ico} " . htmlspecialchars($tipo) . "</span>";
}
function htmlHead(string $titulo, string $orden, string $color): string {
    if (!empty($GLOBALS['_pdfEsDevolucion'])) $titulo = 'COMPROBANTE DE DEVOLUCIÓN';
    $estilos = estilosBase($color);
    return "<!DOCTYPE html><html lang='es'><head><meta charset='UTF-8'><title>{$titulo} {$orden}</title><style>{$estilos}</style></head><body>";
}

function _esFilaDevolucionPdf(array $r): bool {
    $d = (string)($r['descripcion'] ?? '');
    return ($r['origen'] ?? '') === 'devolucion' || str_contains($d, '↩️ Devolución') || str_contains($d, 'Devolución de material recogido') || str_contains($d, 'Devolución de stock');
}
function htmlHeader(string $titulo, string $orden, string $badge, string $color, string $logo=''): string {
    if (!empty($GLOBALS['_pdfEsDevolucion'])) { $titulo = 'COMPROBANTE DE DEVOLUCIÓN'; $badge = '↩️ DEVOLUCIÓN'; }
    $logoTag = $logo ? "<img src='{$logo}' style='width:70px;height:70px;object-fit:contain;margin-right:12px;' alt='Logo'>" : '';
    return "
    <div class='header'>
