function _snHtmlPdf(array $doc): string {
    global $pdo;
    $sn = $doc['seriales'] ?? null;
    if ($sn === null) {
        $d2 = $doc;
        if (empty($d2['solicitud_id']) && !empty($d2['id']) && !is_numeric($d2['id'])) $d2['solicitud_id'] = $d2['id'];
        try { $sn = ontSerialesDeRegistro($pdo, $d2); } catch (\Throwable $e) { $sn = ''; }
    }
    return $sn ? "<div style='font-size:12px;font-weight:600;color:#475569;margin-top:3px;'>SN: " . htmlspecialchars($sn) . "</div>" : '';
}
