        ['Despacho',    $fechaEnvio,     'Lleva: ' . $transportador],
        ['Entrega',     $fechaEntrega,   'A: ' . $entregadoA],
        ['Recibido',    $fechaRecibido,  'Por: ' . $recibidoPor],
      ], $color) . "
    " . parsearNotas($notasRaw) . "

    <div class='firmas'>
      <div class='firma'>
        <div class='firma-linea'>
          <div class='firma-nombre'>" . htmlspecialchars($nombreSol ?: $solicitante) . "</div>
          <div class='firma-cargo'>Solicitante &mdash; {$destino}</div>
        </div>
      </div>
      <div class='firma'>
        <div class='firma-linea'>
          <div class='firma-nombre'>{$aprobadoPor}</div>
          <div class='firma-cargo'>Aprobó &mdash; Almacén Central</div>
        </div>
      </div>
      <div class='firma'>
        <div class='firma-linea'>
          <div class='firma-nombre'>_____________________</div>
          <div class='firma-cargo'>Recibido por &mdash; {$destino}</div>
        </div>
      </div>
    </div>

    <div class='footer'>
      <span>Integrados S&amp;S &mdash; Sistema de Inventario</span>
      <span>Documento N&deg; {$numOrden} &mdash; Generado el {$fechaGen}</span>
    </div>
    <script>window.onload=function(){window.print();}</script>
    </body></html>";

    return $html;
}

function generarHTMLPedidoMunicipio($numOrden, $color, $estadoLabel, $doc, $nombreSol, $fechaSol, $fechaResp, $logo=''): string {
    $producto    = htmlspecialchars($doc['nombre'] ?? '') . _snHtmlPdf($doc);
    $ref         = htmlspecialchars($doc['ref'] ?? '');
    $unidad      = $doc['unidad_pedido'] ?? 'unidad';
    $municipio   = htmlspecialchars($doc['municipio'] ?? '');
    $solicitante = htmlspecialchars($doc['solicitado_por'] ?? '');
    $cantidad    = (int)($doc['cantidad'] ?? 0);
    $justif      = htmlspecialchars($doc['justificacion'] ?? '');
    $motivo      = htmlspecialchars($doc['motivo'] ?? '');
    $fechaGen    = date('d/m/Y H:i');

    $justifBox = $justif ? "<div class='ibox gris'><div class='ibox-titulo'>Justificación</div><p>{$justif}</p></div>" : '';
    $motivoBox = $motivo ? "<div class='ibox rojo'><div class='ibox-titulo'>Motivo de rechazo</div><p>{$motivo}</p></div>" : '';

    $html = htmlHead("REMISIÓN DE PEDIDO", $numOrden, $color);
    $html .= htmlHeader("REMISIÓN DE PEDIDO AL ALMACÉN", $numOrden, $estadoLabel, $color, $logo);

    $html .= "
    <div class='seccion'>Producto</div>
    <div style='background:#F8FAFC;border:1.5px solid #E2E8F0;border-left:4px solid {$color};border-radius:10px;padding:16px 20px;margin-bottom:18px;'>
      <div style='font-size:11px;font-family:monospace;color:{$color};background:white;padding:2px 8px;border-radius:5px;display:inline-block;border:1px solid #E2E8F0;margin-bottom:6px;'>REF: {$ref}</div>
      <div style='font-size:18px;font-weight:800;color:#0F172A;'>{$producto}</div>
      <div style='font-size:32px;font-weight:900;color:{$color};margin-top:8px;'>{$cantidad}<span style='font-size:13px;font-weight:600;color:#94A3B8;margin-left:5px;'>{$unidad}(s)</span></div>
    </div>

    <div class='seccion'>Información del pedido</div>
    <div class='grid3'>
      <div class='campo'><label>Solicitante</label><span>" . htmlspecialchars($nombreSol ?: $solicitante) . "</span></div>
      <div class='campo'><label>Usuario</label><span>{$solicitante}</span></div>
      <div class='campo dest'><label>Municipio</label><span>{$municipio}</span></div>
      <div class='campo'><label>Fecha de pedido</label><span>{$fechaSol}</span></div>
      <div class='campo'><label>Fecha de respuesta</label><span>{$fechaResp}</span></div>
      <div class='campo'><label>Estado</label><span>{$estadoLabel}</span></div>
    </div>

    {$justifBox}
    {$motivoBox}

    <div class='firmas'>
      <div class='firma'>
        <div class='firma-linea'>
          <div class='firma-nombre'>" . htmlspecialchars($nombreSol ?: $solicitante) . "</div>
          <div class='firma-cargo'>Solicitante &mdash; {$municipio}</div>
        </div>
      </div>
      <div class='firma'>
        <div class='firma-linea'>
          <div class='firma-nombre'>Administrador</div>
          <div class='firma-cargo'>Aprobó &mdash; Almacén Central</div>
        </div>
      </div>
      <div class='firma'>
        <div class='firma-linea'>
          <div class='firma-nombre'>_____________________</div>
          <div class='firma-cargo'>Recibido por &mdash; {$municipio}</div>
        </div>
      </div>
    </div>

    <div class='footer'>
      <span>Integrados S&amp;S &mdash; Sistema de Inventario</span>
      <span>Documento N&deg; {$numOrden} &mdash; Generado el {$fechaGen}</span>
    </div>
    <script>window.onload=function(){window.print();}</script>
    </body></html>";

    return $html;
}

responder(['error' => 'Accion no reconocida'], 400);
